#include <cstdio.h>
#include <cstdlib.h>
#include <cstring.h>
#include <unistd.h>
#include <time.h>
#include <termios.h>
#include <sys/select.h>
#include <ncurses.h>

#define VERSION "2.0"
#define DEFAULT_DELAY 4
#define MAX_DELAY 10
#define MIN_DELAY 0

typedef enum {
    COLOR_GREEN, COLOR_RED, COLOR_BLUE, COLOR_WHITE,
    COLOR_YELLOW, COLOR_CYAN, COLOR_MAGENTA, COLOR_BLACK
} Color;

typedef struct {
    int async, bold, all_bold, no_bold, force_term, linux_mode, old_scroll;
    int shadows, lock, rainbow, every_char, lambda_mode, x_mode, screensaver;
    int use_japanese, delay;
    Color color;
    char *message, *tty;
} Options;

static Options opts = {
    .async = 0, .bold = 0, .all_bold = 0, .no_bold = 1,
    .force_term = 0, .linux_mode = 0, .old_scroll = 0,
    .shadows = 0, .lock = 0, .rainbow = 0, .every_char = 0,
    .lambda_mode = 0, .x_mode = 0, .screensaver = 0,
    .use_japanese = 0, .delay = DEFAULT_DELAY,
    .color = COLOR_GREEN, .message = NULL, .tty = NULL
};

static const char *colors[] = {
    "green", "red", "blue", "white", "yellow", "cyan", "magenta", "black"
};

static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void) {
    printf(" CMatrix version %s (compiled 22:13:51, Jun 11 2026)\n", VERSION);
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

static int parse_color(const char *str) {
    if (str == NULL) return COLOR_GREEN;
    for (int i = 0; i < 8; i++) {
        if (strcasecmp(str, colors[i]) == 0) return (Color)i;
    }
    printf(" Invalid color selection\n");
    printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
    return -1;
}

static void parse_args(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-V") == 0) {
            print_version();
            exit(0);
        } else if (strcmp(argv[i], "-a") == 0) { opts.async = 1; }
        else if (strcmp(argv[i], "-b") == 0) { opts.bold = 1; }
        else if (strcmp(argv[i], "-B") == 0) { opts.all_bold = 1; opts.bold = 1; }
        else if (strcmp(argv[i], "-c") == 0) { opts.use_japanese = 1; }
        else if (strcmp(argv[i], "-f") == 0) { opts.force_term = 1; }
        else if (strcmp(argv[i], "-l") == 0) { opts.linux_mode = 1; }
        else if (strcmp(argv[i], "-L") == 0) { opts.lock = 1; }
        else if (strcmp(argv[i], "-o") == 0) { opts.old_scroll = 1; }
        else if (strcmp(argv[i], "-n") == 0) { opts.no_bold = 1; opts.bold = 0; opts.all_bold = 0; }
        else if (strcmp(argv[i], "-s") == 0) { opts.screensaver = 1; }
        else if (strcmp(argv[i], "-x") == 0) { opts.x_mode = 1; }
        else if (strcmp(argv[i], "-r") == 0) { opts.rainbow = 1; }
        else if (strcmp(argv[i], "-m") == 0) { opts.lambda_mode = 1; }
        else if (strcmp(argv[i], "-k") == 0) { opts.every_char = 1; }
        else if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 < argc) {
                opts.delay = atoi(argv[++i]);
                if (opts.delay < MIN_DELAY) opts.delay = MIN_DELAY;
                if (opts.delay > MAX_DELAY) opts.delay = MAX_DELAY;
            } else {
                printf("Error: -u requires a delay value (0-10)\n");
                exit(1);
            }
        } else if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 < argc) {
                opts.color = parse_color(argv[++i]);
                if (opts.color < 0) exit(1);
            } else {
                printf("Error: -C requires a color value\n");
                exit(1);
            }
        } else if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 < argc) { opts.message = argv[++i]; }
            else { opts.message = "Welcome to the Matrix"; }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 < argc) { opts.tty = argv[++i]; }
        } else {
            printf("Unknown option: %s\n", argv[i]);
            print_usage();
            exit(1);
        }
    }
}
